      interactive
    } else {
      Link(destination: url) { label() }
    }
  }

  @available(iOS 17, *)
  @ViewBuilder var interactive: some View {
    switch kind {
    case .native:
      Button(intent: FNWActionIntent(url: url)) { label() }.buttonStyle(.plain)
    case .callback:
      Button(intent: FNWCallbackIntent(url: url, appGroup: FNW.appGroup)) { label() }
        .buttonStyle(.plain)
    case .open:
      Link(destination: url) { label() }
    }
  }
}

/// Clock face with hour and minute hands, redrawn every minute by the
/// timeline. iOS widgets cannot animate, so there is no second hand.
struct FNWAnalogClock: View {
  let date: Date
  let size: CGFloat
  let face: Color
  let border: Color?
  let ticks: Color
  let hands: Color
  let allTicks: Bool

  var body: some View {
    let calendar = Calendar.current
    let hour = Double(calendar.component(.hour, from: date) % 12)
    let minute = Double(calendar.component(.minute, from: date))
    ZStack {
      Circle().fill(face)
      if let border = border {
        Circle().strokeBorder(border, lineWidth: size * 0.02)
      }
      ForEach(0..<12, id: \.self) { i in
        if allTicks || i % 3 == 0 {
          Capsule()
            .fill(ticks)
            .frame(width: size * (i % 3 == 0 ? 0.035 : 0.022), height: size * (i % 3 == 0 ? 0.07 : 0.04))
            .offset(y: -size * 0.395)
            .rotationEffect(.degrees(Double(i) * 30))
        }
      }
      hand(length: 0.23, width: 0.055, degrees: (hour + minute / 60) * 30)
      hand(length: 0.38, width: 0.035, degrees: minute * 6)
      Circle().fill(hands).frame(width: size * 0.07, height: size * 0.07)
    }
    .frame(width: size, height: size)
  }

  private func hand(length: CGFloat, width: CGFloat, degrees: Double) -> some View {
    Capsule()
      .fill(hands)
      .frame(width: size * width, height: size * length)
      .offset(y: -size * length / 2)
      .rotationEffect(.degrees(degrees))
  }
}

