      .widgetURL(URL(string: "fnw://open?homeWidget&w=Weather"))
  }

  @ViewBuilder var content: some View {
    main
  }

  @ViewBuilder var main: some View {
    ZStack(alignment: .topLeading) {
      VStack(alignment: .leading, spacing: 0) {
        HStack(alignment: .center, spacing: 4) {
          Image(systemName: "mappin.and.ellipse")
            .resizable()
            .scaledToFit()
            .frame(width: 14, height: 14)
            .foregroundColor(FNW.color(0xFFFFFFFF, 0xFFFFFFFF))
          Text(verbatim: FNW.resolve("{city}", entry.v))
            .font(.system(size: 14, weight: .semibold))
            .foregroundColor(FNW.color(0xFFFFFFFF, 0xFFFFFFFF))
            .multilineTextAlignment(.leading)
        }
        Spacer(minLength: 0)
        (Text(verbatim: FNW.resolve("{temp}", entry.v)).font(.system(size: 44, weight: .light)).foregroundColor(FNW.color(0xFFFFFFFF, 0xFFFFFFFF))
          + Text(verbatim: "°C").font(.system(size: 18, weight: .regular)).foregroundColor(FNW.color(0xFFFFFFFF, 0xFFFFFFFF)))
          .multilineTextAlignment(.leading)
        Spacer(minLength: 0)
        VStack(alignment: .leading, spacing: 0) {
          Text(verbatim: FNW.resolve("{sky}", entry.v))
            .font(.system(size: 12, weight: .regular))
            .foregroundColor(FNW.color(0xFFFFFFFF, 0xFFFFFFFF))
            .lineLimit(1)
            .multilineTextAlignment(.leading)
          Text(verbatim: FNW.resolve("Feels like {feels}°", entry.v))
            .font(.system(size: 11, weight: .regular))
            .foregroundColor(FNW.color(0xFFE0F2FE, 0xFFE0F2FE))
            .multilineTextAlignment(.leading)
        }
      }
    }
      .padding(EdgeInsets(top: 14, leading: 14, bottom: 14, trailing: 14))
      .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .topLeading)
      .background(RoundedRectangle(cornerRadius: 0, style: .continuous).fill(LinearGradient(colors: [FNW.color(0xFF2F80ED, 0xFF2F80ED), FNW.color(0xFF56CCF2, 0xFF1E3A8A)], startPoint: .topLeading, endPoint: .bottomTrailing)))
      .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .topLeading)
  }

}

